import type { Signal, TradeRange } from './types';
import { coin } from './types';

const DARK = {
  tooltip: { backgroundColor: '#161b22', borderColor: '#30363d', textStyle: { color: '#e0e0e0', fontSize: 11, fontFamily: 'monospace' } },
  axis: { color: '#484f58', fontSize: 9, fontFamily: 'monospace' },
  grid: { color: '#30363d' },
  split: { color: '#21262d' },
};

const Z_THRESHOLDS = [
  { yAxis: 2, lineStyle: { color: '#f8514966' }, label: { color: '#f85149', formatter: '2' } },
  { yAxis: 1, lineStyle: { color: '#ff980044' }, label: { color: '#ff9800', formatter: '1' } },
  { yAxis: 0, lineStyle: { color: '#30363d', type: 'solid' as const }, label: { color: '#484f58', formatter: '0' } },
  { yAxis: -1, lineStyle: { color: '#64ffda44' }, label: { color: '#64ffda', formatter: '-1' } },
  { yAxis: -2, lineStyle: { color: '#4caf5066' }, label: { color: '#4caf50', formatter: '-2' } },
];

export function buildBtcChart(labels: string[], ohlc: number[][]) {
  return {
    backgroundColor: 'transparent', animation: false,
    grid: { top: 25, right: 50, bottom: 45, left: 60 },
    tooltip: { trigger: 'axis', ...DARK.tooltip },
    legend: { data: ['BTC'], textStyle: { color: '#ffd54f', fontSize: 11 }, top: 0 },
    dataZoom: [],
    xAxis: { type: 'category', data: labels, axisLabel: DARK.axis, axisLine: { lineStyle: { color: DARK.grid.color } } },
    yAxis: { type: 'value', scale: true, axisLabel: DARK.axis, splitLine: { lineStyle: { color: DARK.split.color } } },
    series: [{ name: 'BTC', type: 'candlestick', data: ohlc, itemStyle: { color: '#4caf50', color0: '#f85149', borderColor: '#4caf50', borderColor0: '#f85149' } }],
  };
}

export function buildPairChart(
  pair: string,
  labels: string[],
  prices: number[],
  pzData: number[],
  szData: number[],
  signals: Signal[],
  tradeRanges: TradeRange[],
  frameIndex: number,
  color: string,
) {
  const entryPoints: unknown[] = [];
  const exitPoints: unknown[] = [];
  for (const sig of signals) {
    if (sig.index > frameIndex) break;
    if (sig.type === 'entry') {
      entryPoints.push({
        coord: [sig.index, sig.price || prices[sig.index]],
        symbol: 'triangle', symbolSize: 12, symbolRotate: sig.side === 'short' ? 180 : 0,
        itemStyle: { color: sig.side === 'long' ? '#4caf50' : '#f85149' },
        label: { show: true, formatter: sig.tag.replace('mr_', '').replace('_a', ' A').replace('_b', ' B'), position: 'bottom', fontSize: 9, color: sig.side === 'long' ? '#4caf50' : '#f85149' },
      });
    } else {
      exitPoints.push({
        coord: [sig.index, prices[sig.index] || 0],
        symbol: 'diamond', symbolSize: 10,
        itemStyle: { color: sig.win ? '#4caf50' : '#f85149' },
        label: { show: true, formatter: `${sig.profit_pct}%`, position: 'top', fontSize: 9, fontWeight: 'bold', color: sig.win ? '#4caf50' : '#f85149' },
      });
    }
  }

  const markAreas = tradeRanges
    .filter((tr) => tr.entry_index <= frameIndex)
    .map((tr) => [
      { xAxis: tr.entry_index, itemStyle: { color: tr.win === null ? 'rgba(100,255,218,0.08)' : tr.win ? 'rgba(76,175,80,0.08)' : 'rgba(248,81,73,0.08)' } },
      { xAxis: Math.min(tr.exit_index, frameIndex) },
    ]);

  return {
    backgroundColor: 'transparent', animation: false,
    grid: [
      { top: 25, right: 50, bottom: '45%', left: 50 },
      { top: '60%', right: 50, bottom: 25, left: 50 },
    ],
    tooltip: { trigger: 'axis', ...DARK.tooltip },
    legend: { data: [coin(pair), 'Pair Z', 'Spread Z'], textStyle: { color: '#8b949e', fontSize: 9 }, top: 0 },
    axisPointer: { link: [{ xAxisIndex: 'all' }] },
    dataZoom: [],
    xAxis: [
      { type: 'category', data: labels, gridIndex: 0, axisLabel: { show: false }, axisLine: { lineStyle: { color: DARK.grid.color } } },
      { type: 'category', data: labels, gridIndex: 1, axisLabel: { ...DARK.axis, fontSize: 8 }, axisLine: { lineStyle: { color: DARK.grid.color } } },
    ],
    yAxis: [
      { type: 'value', gridIndex: 0, scale: true, axisLabel: DARK.axis, splitLine: { lineStyle: { color: DARK.split.color } } },
      { type: 'value', gridIndex: 1, axisLabel: DARK.axis, splitLine: { lineStyle: { color: DARK.split.color } } },
    ],
    series: [
      {
        name: coin(pair), type: 'line', data: prices, xAxisIndex: 0, yAxisIndex: 0,
        smooth: false, symbol: 'none', lineStyle: { color, width: 2 }, areaStyle: { color: `${color}0d` },
        markPoint: { data: [...entryPoints, ...exitPoints] },
        markArea: { silent: true, data: markAreas },
      },
      {
        name: 'Pair Z', type: 'line', data: pzData, xAxisIndex: 1, yAxisIndex: 1,
        smooth: true, symbol: 'none', lineStyle: { color: '#64ffda', width: 1.5 },
        markLine: { silent: true, symbol: 'none', lineStyle: { type: 'dashed', width: 1 }, label: { position: 'end', fontSize: 8, fontFamily: 'monospace' }, data: Z_THRESHOLDS },
      },
      {
        name: 'Spread Z', type: 'line', data: szData, xAxisIndex: 1, yAxisIndex: 1,
        smooth: true, symbol: 'none', lineStyle: { color: '#ffd54f', width: 1, type: 'dashed' },
      },
    ],
  };
}

export function buildEquityChart(labels: string[], equity: number[], initial: number) {
  const current = equity.length > 0 ? equity[equity.length - 1] : initial;
  const profit = current - initial;
  const profitPct = ((current / initial - 1) * 100).toFixed(1);
  const legend = `Equity $${current.toFixed(1)} (${profitPct}%)`;
  return {
    option: {
      backgroundColor: 'transparent', animation: false,
      grid: { top: 25, right: 50, bottom: 25, left: 60 },
      tooltip: { trigger: 'axis', ...DARK.tooltip },
      legend: { data: [legend], textStyle: { color: profit >= 0 ? '#4caf50' : '#f85149', fontSize: 12 }, top: 0 },
      xAxis: { type: 'category', data: labels, axisLabel: { ...DARK.axis, fontSize: 8 }, axisLine: { lineStyle: { color: DARK.grid.color } } },
      yAxis: { type: 'value', scale: true, axisLabel: { ...DARK.axis, formatter: '${value}' }, splitLine: { lineStyle: { color: DARK.split.color } } },
      series: [{
        name: legend, type: 'line', data: equity, smooth: false, symbol: 'none',
        lineStyle: { color: profit >= 0 ? '#4caf50' : '#f85149', width: 2 },
        areaStyle: { color: profit >= 0 ? 'rgba(76,175,80,0.08)' : 'rgba(248,81,73,0.08)' },
      }],
    },
    current, profit: profit.toFixed(2), profitPct,
  };
}
