<script setup lang="ts">
const props = defineProps<{
  totalFrames: number;
  frameIndex: number;
  currentTimestamp: string;
  playing: boolean;
  playSpeed: number;
  progressPct: string;
  browseStart: string;
  browseEnd: string;
  loading: boolean;
  visibleCandles: number;
  detached?: boolean;
  strategyName?: string;
  strategyTimeframe?: string;
}>();

const emit = defineEmits<{
  seek: [idx: number];
  step: [delta: number];
  togglePlay: [];
  load: [];
  'update:browseStart': [val: string];
  'update:browseEnd': [val: string];
  'update:playSpeed': [val: number];
  'update:visibleCandles': [val: number];
  'toggle:detach': [];
}>();

const BTN = 'px-3 py-1 rounded-sm text-lg';
const BTN_STYLE = 'background:#21262d;color:#8b949e;border:1px solid #30363d;cursor:pointer';
</script>

<template>
  <div class="rounded-md dark:bg-surface-900 dark:border-surface-700 border p-4">
    <div class="flex items-center gap-3 mb-3">
      <span class="text-xl font-bold" style="color: #64ffda">Monitor2</span>
      <span v-if="strategyName" class="px-2 py-1 rounded-sm text-base font-bold" style="background: #7c4dff20; color: #b388ff; border: 1px solid #7c4dff33">{{ strategyName }}</span>
      <span v-if="strategyTimeframe" class="px-2 py-1 rounded-sm text-base font-bold" style="background: #ff980020; color: #ff9800; border: 1px solid #ff980033">{{ strategyTimeframe }}</span>
      <span class="text-base text-muted-color">Start:</span>
      <input :value="browseStart" type="date" class="text-base px-2 py-1 rounded-sm border dark:border-surface-700 dark:bg-surface-900" @input="emit('update:browseStart', ($event.target as HTMLInputElement).value)" />
      <span class="text-base text-muted-color">End:</span>
      <input :value="browseEnd" type="date" class="text-base px-2 py-1 rounded-sm border dark:border-surface-700 dark:bg-surface-900" @input="emit('update:browseEnd', ($event.target as HTMLInputElement).value)" />
      <button class="px-4 py-2 rounded-md text-base font-bold" style="background:#238636;color:#fff;border:none;cursor:pointer" @click="emit('load')">Load</button>
      <span class="text-base text-muted-color ms-auto">{{ totalFrames }} candles</span>
      <button
        class="px-2 py-1 rounded-sm text-base"
        :style="{ background: detached ? '#7c4dff20' : '#21262d', color: detached ? '#b388ff' : '#8b949e', border: `1px solid ${detached ? '#7c4dff' : '#30363d'}`, cursor: 'pointer' }"
        :title="detached ? 'Pin back to page' : 'Detach as floating panel'"
        @click="emit('toggle:detach')"
      >{{ detached ? '📌 Pin' : '🔓 Detach' }}</button>
    </div>

    <div v-if="totalFrames > 0">
      <div class="flex justify-between text-base text-muted-color mb-1">
        <span>{{ browseStart }}</span>
        <span class="font-bold text-lg" style="color: #ffd54f">{{ currentTimestamp }}</span>
        <span>{{ browseEnd }}</span>
      </div>

      <input type="range" :min="0" :max="Math.max(0, totalFrames - 1)" :value="frameIndex"
        @input="emit('seek', parseInt(($event.target as HTMLInputElement).value))"
        style="width: 100%; height: 28px; cursor: pointer; accent-color: #7c4dff;" />

      <div class="flex items-center gap-2 mt-2">
        <button :class="BTN" :style="BTN_STYLE" @click="emit('seek', 0)">|&lt;</button>
        <button :class="BTN" :style="BTN_STYLE" @click="emit('step', -10)">-10</button>
        <button :class="BTN" :style="BTN_STYLE" @click="emit('step', -1)">-1</button>
        <button class="px-5 py-1 rounded-sm text-lg font-bold"
          :style="{ background: playing ? '#f85149' : '#4caf50', color: '#fff', border: 'none', cursor: 'pointer' }"
          @click="emit('togglePlay')">{{ playing ? 'Pause' : 'Play' }}</button>
        <button :class="BTN" :style="BTN_STYLE" @click="emit('step', 1)">+1</button>
        <button :class="BTN" :style="BTN_STYLE" @click="emit('step', 10)">+10</button>
        <button :class="BTN" :style="BTN_STYLE" @click="emit('seek', totalFrames - 1)">&gt;|</button>

        <span class="text-base text-muted-color ms-2">Speed:</span>
        <select :value="playSpeed" @change="emit('update:playSpeed', parseInt(($event.target as HTMLSelectElement).value))"
          class="text-base px-2 py-1 rounded-sm border dark:border-surface-700 dark:bg-surface-900">
          <option :value="1000">1s</option><option :value="500">0.5s</option>
          <option :value="200">0.2s</option><option :value="100">0.1s</option><option :value="50">50ms</option>
        </select>

        <span class="text-base text-muted-color ms-2">View:</span>
        <select :value="visibleCandles" @change="emit('update:visibleCandles', parseInt(($event.target as HTMLSelectElement).value))"
          class="text-base px-2 py-1 rounded-sm border dark:border-surface-700 dark:bg-surface-900">
          <option :value="50">50</option><option :value="100">100</option>
          <option :value="200">200</option><option :value="500">500</option><option :value="0">All</option>
        </select>

        <div class="flex-1 ms-3" style="height: 8px; background: #161b22; border-radius: 4px; overflow: hidden;">
          <div :style="{ width: progressPct + '%', height: '100%', background: 'linear-gradient(90deg, #7c4dff, #b388ff)', transition: 'width 0.1s' }"></div>
        </div>
        <span class="text-base font-bold" style="color: #b388ff">{{ progressPct }}%</span>
        <span class="text-base text-muted-color">F{{ frameIndex + 1 }}/{{ totalFrames }}</span>
      </div>
    </div>
    <div v-if="loading" class="mt-2 text-base text-muted-color">Loading data...</div>
  </div>
</template>
